module tb;
    reg clk;
    reg rst_n;
    reg [15:0] seed;
    reg ld;
    reg step;
    wire [15:0] state;
    wire out;
    reg [15:0] exp;
    integer i;

    sparc_ifu_esl_lfsr dut(
        .clk(clk), .rst_n(rst_n), .lfsr_seed(seed), .lfsr_ld(ld),
        .lfsr_step(step), .lfsr_state_f(state), .lfsr_out_f(out)
    );

    always #5 clk = ~clk;

    function [15:0] next_lfsr;
        input [15:0] s;
        begin
            next_lfsr = {s[14:0], s[15] ^ s[13] ^ s[12] ^ s[10]};
        end
    endfunction

    task check;
        input [15:0] expected;
        begin
            #1;
            if (state !== expected || out !== expected[15]) begin
                $display("LFSR mismatch: expected %h/%b got %h/%b", expected, expected[15], state, out);
                $finish;
            end
        end
    endtask

    initial begin
        clk = 0; rst_n = 0; seed = 0; ld = 0; step = 0; exp = 0;
        repeat (2) @(posedge clk);
        rst_n = 1;
        @(posedge clk); check(16'h0000);

        seed = 16'h0001; ld = 1; step = 1;
        @(posedge clk); check(16'h0001);

        ld = 0; step = 1; exp = 16'h0001;
        for (i = 0; i < 64; i = i + 1) begin
            exp = next_lfsr(exp);
            @(posedge clk); check(exp);
        end

        seed = 16'hace1; ld = 1; step = 0;
        @(posedge clk); check(16'hace1);
        ld = 0; step = 1; exp = 16'hace1;
        for (i = 0; i < 65535; i = i + 1) begin
            exp = next_lfsr(exp);
            @(posedge clk); check(exp);
        end
        if (state !== 16'hace1) begin
            $display("LFSR period mismatch: got %h", state);
            $finish;
        end

        step = 0;
        repeat (3) @(posedge clk); check(16'hace1);
        $display("LFSR unit PASS");
        $finish;
    end
endmodule
