    reg ld;
    reg step;
    wire [15:0] state;
    wire out;
    reg [15:0] exp;
    integer i;

    sparc_ifu_esl_lfsr dut(
        .clk(clk), .rst_n(rst_n), .lfsr_seed(seed), .lfsr_ld(ld),
        .lfsr_step(step), .lfsr_state_f(state), .lfsr_out_f(out)
    );

    always #5 clk = ~clk;

    function [15:0] next_lfsr;
        input [15:0] s;
        begin
            next_lfsr = {s[14:0], s[15] ^ s[13] ^ s[12] ^ s[10]};
        end
    endfunction

    task check;
        input [15:0] expected;
        begin
            #1;
            if (state !== expected || out !== expected[15]) begin
                $display("LFSR mismatch: expected %h/%b got %h/%b", expected, expected[15], state, out);
                $finish;
            end
        end
