        repeat (2) @(posedge clk);
        rst_n = 1;
        @(posedge clk); check(16'h0000);
        seed = 16'h0001; ld = 1; step = 1;
        @(posedge clk); check(16'h0001);
        ld = 0; step = 1; exp = 16'h0001;
        for (i = 0; i < 64; i = i + 1) begin
            exp = next_lfsr(exp);
            @(posedge clk); check(exp);
        end
        seed = 16'hace1; ld = 1; step = 0;
        @(posedge clk); check(16'hace1);
        ld = 0; step = 1; exp = 16'hace1;
        for (i = 0; i < 65535; i = i + 1) begin
