            @(posedge clk); check(exp);
        end
        if (state !== 16'hace1) begin
            $display("LFSR period mismatch: got %h", state);
            $finish;
        end
        step = 0;
        repeat (3) @(posedge clk); check(16'hace1);
        $display("LFSR unit PASS");
        $finish;
    end
endmodule
