module uart_serializer
#(
    parameter PACKET_LEN_BYTES = 30,
    parameter PACKET_LEN_BYTES_LOG2 = 5
)
(
    input                                       clk,
    input                                       rst_n,

    input                                       pkt_val,
    input  [(PACKET_LEN_BYTES*8)-1:0]           pkt_data,
    output                                      pkt_rdy,

    output                                      uart_val,
    output [7:0]                                uart_data,
    input                                       uart_rdy
);

    localparam PACKET_LEN_BITS = PACKET_LEN_BYTES * 8;
    localparam [PACKET_LEN_BYTES_LOG2-1:0] LAST_BYTE =
        PACKET_LEN_BYTES - 1'b1;

    reg [PACKET_LEN_BITS-1:0]                   pkt_shift_f;
    reg [PACKET_LEN_BYTES_LOG2-1:0]             byte_count_f;
    reg                                         active_f;

    wire                                        pkt_fire;
    wire                                        uart_fire;

    assign pkt_rdy = ~active_f;
    assign uart_val = active_f;
    assign uart_data = pkt_shift_f[PACKET_LEN_BITS-1:PACKET_LEN_BITS-8];

    assign pkt_fire = pkt_val & pkt_rdy;
    assign uart_fire = uart_val & uart_rdy;

    always @(posedge clk)
    begin
        if (~rst_n)
        begin
            pkt_shift_f <= {PACKET_LEN_BITS{1'b0}};
            byte_count_f <= {PACKET_LEN_BYTES_LOG2{1'b0}};
            active_f <= 1'b0;
