        else if (active_f)
        begin
            if (uart_fire)
            begin
                if (byte_count_f == LAST_BYTE)
                begin
                    pkt_shift_f <= {PACKET_LEN_BITS{1'b0}};
                    byte_count_f <= {PACKET_LEN_BYTES_LOG2{1'b0}};
